$('#signupForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),f=Object.fromEntries(fd);if(accounts.some(x=>x.email===f.email))return toast('이미 가입된 이메일이에요.');const a={id:crypto.randomUUID(),name:f.name,email:f.email,role:f.role,homeLocation:f.homeLocation||f.storeAddress,passwordHash:await hash(f.password)};accounts.push(a);if(f.role==='owner'){const [lat,lng]=locationCoords(f.storeAddress);places.push({id:crypto.randomUUID(),ownerId:a.id,name:f.storeName,area:f.storeAddress,type:'cafe',lat,lng,image:await resizeImage(fd.get('storeImage')),hours:f.open24?'24시간 운영':'영업시간 등록 필요',menus:[[f.firstMenu,+f.firstPrice,'']],desc:'점주가 등록한 가게',cozy:!!f.cozy,quiet:!!f.quiet,open24:!!f.open24,solo:!!f.solo,groupFriendly:!!f.groupFriendly,parking:false,publicParking:false,pet:false,quietTimes:[],reviews:[],reservable:true});store.set('places',places)}store.set('accounts',accounts);$('#signupDialog').close();populatePlaces();render();setSession(a,true);toast('가입이 완료됐어요.')};
