function openPayment(id){const b=bookings.find(x=>x.id===id),p=places.find(x=>x.id===b.placeId);$('#paymentForm').dataset.booking=id;$('#paymentSummary').innerHTML=`<div class="payment-total"><span>${p.name} · ${b.party}명</span><b>${money(b.party*10000)}</b></div>`;$('#paymentCoupon').innerHTML='<option value="">쿠폰 사용 안 함</option>'+coupons.filter(c=>c.placeId===p.id&&c.claimedBy?.includes(session?.id)).map(c=>`<option value="${c.id}">${c.title} - ${money(c.discount)}</option>`).join('');$('#paymentDialog').showModal()}
