async function geocodeAddress(query){try{const u=`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=kr&q=${encodeURIComponent(query)}`,r=await fetch(u,{headers:{'Accept-Language':'ko'}}),j=await r.json();if(j[0])return[+j[0].lat,+j[0].lon]}catch(e){}return locationCoords(query)}
function addVote(p,key,userId){p.featureVotes=p.featureVotes||{};p.featureVoters=p.featureVoters||{};p.featureVoters[key]=p.featureVoters[key]||[];if(p.featureVoters[key].includes(userId))return false;p.featureVoters[key].push(userId);p.featureVotes[key]=(p.featureVotes[key]||0)+1;return true}
function sortedFeatures(p){return Object.entries(featureLabels).filter(([k])=>p[k]||p.featureVotes?.[k]).sort((a,b)=>(p.featureVotes?.[b[0]]||0)-(p.featureVotes?.[a[0]]||0))}
