async function resolveAddress(query){const fallback=locationCoords(query);try{const params=new URLSearchParams({format:'json',limit:'5',countrycodes:'kr',addressdetails:'1',bounded:'1',viewbox:'126.25,37.85,127.25,37.25',q:`${query}, 대한민국`}),r=await fetch(`https://nominatim.openstreetmap.org/search?${params}`,{headers:{'Accept-Language':'ko'}}),items=await r.json(),best=items.find(x=>/서울|인천/.test(x.display_name))||items[0];if(best)return{lat:+best.lat,lng:+best.lon,label:best.display_name}}catch(e){}return{lat:fallback[0],lng:fallback[1],label:query}}
