setBookingStatus=function(id,status){if(session?.role!=='owner')return toast('점주만 예약 상태를 변경할 수 있어요.');const b=bookings.find(x=>x.id===id),p=places.find(x=>x.id===b?.placeId);if(!b||p.ownerId!==session.id)return toast('본인 가게 예약만 관리할 수 있어요.');b.status=status;if(status==='이용완료'){visited.add(b.placeId);store.set('visited',[...visited])}store.set('bookings',bookings);renderBookings();render();toast(`예약을 ${status} 처리했어요.`)};
function renderUserAccount(){const mine=bookings.filter(b=>b.userId===session.id);$('#accountSummary').innerHTML=`<p><b>${session.name}</b><br>${session.email}</p><form id="homeUpdateForm"><label>내 기준 주소<input name="homeLocation" value="${session.homeLocation||''}" required></label><button class="secondary">주소 저장</button></form><h3>내 예약</h3><div class="my-bookings">${mine.length?mine.map(b=>{const p=places.find(x=>x.id===b.placeId);return `<p><b>${p?.name}</b><span>${b.status}</span><br>${b.date.replace('T',' ')} · ${b.party}명 · ${b.phone||''}</p>`}).join(''):'<small>예약 내역이 없어요.</small>'}</div>`;$('#homeUpdateForm').onsubmit=async e=>{e.preventDefault();const q=new FormData(e.target).get('homeLocation'),loc=await resolveAddress(q),a=accounts.find(x=>x.id===session.id);session.homeLocation=q;session.homeCoords=[loc.lat,loc.lng];if(a){a.homeLocation=q;a.homeCoords=session.homeCoords;store.set('accounts',accounts)}localStorage.setItem('masil_session',JSON.stringify(session));map.setView(session.homeCoords,15);toast('내 기준 주소를 저장했어요.')}}
const mediaDetail=openDetail;openDetail=function(id){mediaDetail(id);const p=places.find(x=>x.id===id),body=$('#detailContent .detail-body'),features=body.querySelector('.feature-grid'),cloud=body.querySelector('.review-cloud'),gallery=body.querySelector('.gallery-strip');body.querySelectorAll('.feature').forEach(x=>{if(x.textContent.includes('편안한 좌석'))x.innerHTML='🛋<br>편안한 쇼파'});if(gallery&&features)features.insertAdjacentElement('afterend',gallery);if(p.menuBoard){const el=document.createElement('div');el.className='menu-board';el.innerHTML=`<h3>대표 메뉴판</h3><img src="${p.menuBoard}" alt="${p.name} 메뉴판">`;gallery?gallery.insertAdjacentElement('afterend',el):features.insertAdjacentElement('afterend',el)}if(cloud)cloud.innerHTML=sortedFeatures(p).map(([k,label])=>{const on=p.featureVoters?.[k]?.includes(session?.id);return `<button class="${on?'selected':''}" onclick="voteFeature('${id}','${k}')"># ${label} <b>${p.featureVotes?.[k]||0}</b></button>`}).join('');const oldReviews=body.querySelector('.reviews-section');if(oldReviews)oldReviews.remove();body.querySelector('.review-form')?.insertAdjacentHTML('beforebegin',`<section class="reviews-section"><h3>방문자 리뷰</h3>${p.reviews.length?p.reviews.map(r=>`<p>${r}</p>`).join(''):'<small>아직 작성된 리뷰가 없어요.</small>'}</section>`);const hero=$('#detailContent .detail-hero');hero.insertAdjacentHTML('beforeend',`<b class="business-badge">${p.businessStatus||'영업 중'}</b>`)};
